_td_page_names_win = ["Main"]


def _td_show_win(name):
    with tdapp.batch():
        _td_apply_win(name)


def _td_apply_win(name):
    if name not in _td_page_names_win:
        raise ValueError("unknown page")
    status.visible = name == "Main"
    tdapp.show_canvases(win, name)


def show_page(name, window=None):
    if window is None:
        window = win
    if window is win:
        return _td_show_win(name)
    raise ValueError("unknown window")

# Event handlers: keep these quick and nonblocking.


def pressed(button):
    status.text = "PRESS: button held"


def released(button):
    status.text = "RELEASE"


def clicked(button):
    status.text = "CLICK: released inside"


def cancelled(button):
    status.text = "CANCEL: released outside"

